-- Farm the City offboarding. Reviewed ownership and identities; application is tracked in d1_migrations.
-- Revalidate target scope and record a recovery bookmark before applying in another environment.
-- Run through D1 migrations (atomic transaction), never statement-by-statement.
-- Shared users, images, global property definitions and object-storage files are retained.
-- Preview may contain fewer project-property and hub-layer assignments than the reviewed archive.
-- Derived memberships, rollups and refresh queues vary by environment and worker progress.
-- In particular, 0096 queues existing features for MTR refresh; those jobs cascade with their feature.
-- Exact resource identities, content counts and external property-use guards remain mandatory.
CREATE TABLE _farmthecity_guard (ok INTEGER NOT NULL CHECK (ok=1));
-- Translation tables lack parent foreign keys in the current schema.
DELETE FROM featureI18n WHERE "featureId" IN (SELECT id FROM "feature" WHERE organisationId='kP31z2fP4-k2' OR layerId IN (SELECT id FROM layer WHERE organisationId='kP31z2fP4-k2' OR projectId IN (SELECT id FROM project WHERE organisationId='kP31z2fP4-k2' OR organisationId IN (SELECT id FROM organisation WHERE id='kP31z2fP4-k2'))));
DELETE FROM layerI18n WHERE "layerId" IN (SELECT id FROM "layer" WHERE organisationId='kP31z2fP4-k2' OR projectId IN (SELECT id FROM project WHERE organisationId='kP31z2fP4-k2' OR organisationId IN (SELECT id FROM organisation WHERE id='kP31z2fP4-k2')));
-- Cascades remove owned resources, roles, assignments, jobs and search documents.
-- Feature-count triggers decrement rollups and invalidate cached counts.
DELETE FROM organisation WHERE id='kP31z2fP4-k2' AND code='farmthecity';
DROP TABLE _farmthecity_guard;
